const beforeP15=render;render=function(){if(location.hash==='#program15-curriculum'){document.getElementById('app').innerHTML=integratedShell('program15-curriculum',heading('Program 15 · Curriculum workspace','Approved build scope · Faculty-review draft')+'<section class="card prose" id="p15-content" aria-live="polite">Loading session package…</section>',model.role);bind();fetch('data/program15-curriculum.json').then(r=>{if(!r.ok)throw Error('Package unavailable');return r.json();}).then(d=>{const n=document.getElementById('p15-content');if(!n)return;n.innerHTML=`<h2>${esc(d.title)}</h2><p>Lead faculty: ${esc(d.leadFaculty)} · Version ${esc(d.version)}</p><p>${esc(d.productOwnerDecision)}</p><p>20 sessions · 60 live hours · 10 weekends. Dates, prices and seats are not configured.</p><h2>Competencies</h2><ul>${d.competencies.map(c=>`<li>${c.id}: ${esc(c.text)}</li>`).join('')}</ul><h2>Session sequence</h2>${d.sessions.map(s=>`<details><summary>${s.id} · Weekend ${s.weekend}, ${s.day} · ${esc(s.title)}</summary><p><strong>Outcome:</strong> ${esc(s.outcome)}</p><p><strong>Build:</strong> ${esc(s.lab)}</p><p><strong>Checkpoint:</strong> ${esc(s.checkpoint)}</p><p>Competency ${s.competency} · Shared module ${s.commons.id}@${s.commons.version}</p><ul>${s.agenda.map(a=>`<li>${a.minutes} minutes: ${esc(a.activity)}</li>`).join('')}</ul><p>${esc(s.makeup)}</p><p>${esc(s.passRule)}</p></details>`).join('')}<h2>Projects</h2>${d.projects.map(p=>`<p><strong>${p.id}: ${esc(p.title)}</strong> · Sessions ${p.sessions.join(', ')}<br>${esc(p.data)}</p>`).join('')}<h2>Capstone rubric</h2><ul>${d.capstoneRubric.map(r=>`<li>${esc(r.criterion)}: ${r.points} points</li>`).join('')}</ul><p>Pass threshold: 70/100, plus mentor-recorded live defense. All module assessments and the final knowledge check must also pass.</p><h2>Before publication</h2><ul>${d.publicationBlockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p>${esc(d.toolsDisclaimer)}</p><a href="data/program15-curriculum.json" download="program15-curriculum.json">Download curriculum package (JSON)</a>`;}).catch(e=>{const n=document.getElementById('p15-content');if(n)n.textContent=e.message;});}else beforeP15();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#program15-curriculum"]'))nav.insertAdjacentHTML('beforeend','<a href="#program15-curriculum">Program 15 curriculum</a>');};render();
